-- Тема 02: варианты ответов выровнены по длине и форме (64 исправлений в 22 вопросах), ключи не меняются.
-- Источник: scripts/questions/068_option_length_topic02.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'К какой базе подключится psql, если имя базы не указано ни в команде, ни в переменных окружения?', 'postgres', 'К базе postgres, созданной вместе с кластером', 'Выбирается по умолчанию, только если так зовут пользователя или это задано явно, например переменной PGDATABASE.', NULL),
        ('option', 'К какой базе подключится psql, если имя базы не указано ни в команде, ни в переменных окружения?', 'template1', 'К базе template1, шаблону новых баз', 'Это шаблон для создания новых баз.', NULL),
        ('option', 'К какой базе подключится psql, если имя базы не указано ни в команде, ни в переменных окружения?', 'К базе с тем же именем, что и пользователь', 'К базе с тем же именем, что у роли', 'Если имя базы нигде не задано, оно совпадает с именем роли, от которой устанавливается подключение.', NULL),
        ('option', 'К какой базе подключится psql, если имя базы не указано ни в команде, ни в переменных окружения?', 'К первой базе по алфавиту', 'К первой по алфавиту базе кластера', 'Такого правила нет.', NULL),
        ('option', 'Какая команда psql показывает параметры текущего подключения?', '\c', '\connect', 'Открывает новое подключение.', '\connect (сокращённо \c) открывает новое подключение.'),
        ('option', 'Какая команда psql показывает параметры текущего подключения?', '\l', '\dconfig', 'Выводит список баз данных.', 'Показывает параметры сервера, а не подключения.'),
        ('option', 'Какая команда psql показывает параметры текущего подключения?', '\du', '\encoding', 'Выводит список ролей.', 'Показывает кодировку клиента, а не параметры подключения.'),
        ('option', 'Что делает \gx в конце запроса?', 'Сохраняет результат в переменные psql', 'Сохраняет результат запроса в переменные psql', 'Так работает команда \gset.', NULL),
        ('option', 'Что делает \gx в конце запроса?', 'Выполняет запрос с расширенным форматом вывода только для этого запроса', 'Выполняет этот запрос с расширенным форматом вывода', 'Расширенный формат применяется только к этому запросу.', 'Расширенный формат применяется только к этому запросу; следующие выводятся как прежде.'),
        ('option', 'Что делает команда \gexec?', 'Выполняет запрос в фоне', 'Выполняет запрос в фоне, не дожидаясь результата', 'Фонового выполнения запросов в psql нет.', NULL),
        ('option', 'Что делает команда \gexec?', 'Выполняет каждое значение результата запроса как отдельную команду SQL', 'Выполняет значения результата как команды SQL', 'Удобно, когда запрос генерирует команды, например через format().', 'Каждое значение результата выполняется как отдельная команда SQL. Удобно, когда запрос генерирует команды, например через format().'),
        ('option', 'Что делает команда \gexec?', 'Выполняет файл скрипта', 'Выполняет команды SQL из указанного файла скрипта', 'Файл со скриптом выполняет команда \i.', NULL),
        ('option', 'Что делает команда \gexec?', 'Выполняет команду ОС', 'Выполняет результат как команду ОС', 'Команду ОС выполняет \!.', 'Команду ОС выполняет \!, а \gexec передаёт значения серверу как команды SQL.'),
        ('option', 'Для чего нужна команда \gset?', 'Задаёт параметр сервера на сеанс', 'Задаёт параметр сервера на время сеанса', 'Параметр сервера задаёт команда SET.', NULL),
        ('option', 'Для чего нужна команда \gset?', 'Сохраняет запрос в историю', 'Сохраняет текст запроса в истории команд', 'История ведётся автоматически, показывает её \s.', NULL),
        ('option', 'Для чего нужна команда \gset?', 'Записывает значения столбцов результата в переменные psql', 'Записывает результат в переменные psql', 'Значения столбцов единственной строки результата попадают в одноимённые переменные (для NULL переменная удаляется).', NULL),
        ('option', 'Для чего нужна команда \gset?', 'Включает вывод без выравнивания', 'Включает вывод без выравнивания столбцов', 'Вывод без выравнивания задаёт \pset format unaligned (\a переключает режим).', NULL),
        ('option', 'В каком порядке выполняются скрипты настройки при запуске psql?', 'Только ~/.psqlrc', '~/.psqlrc, а системный psqlrc пропускается', 'Системный файл, если он есть, тоже выполняется, и раньше личного.', NULL),
        ('option', 'В каком порядке выполняются скрипты настройки при запуске psql?', 'Только системный psqlrc', 'Системный psqlrc, а ~/.psqlrc пропускается', 'Личный ~/.psqlrc тоже выполняется.', NULL),
        ('option', 'Что означает восклицательный знак в приглашении psql, например `student=!#`?', 'Транзакция прервана ошибкой, команды игнорируются до её завершения', 'Транзакция прервана ошибкой и ждёт отката', 'Ошибка прервала транзакцию: нужен ROLLBACK или откат к точке сохранения.', 'Команды игнорируются до конца транзакции: нужен ROLLBACK или откат к точке сохранения.'),
        ('option', 'Что означает восклицательный знак в приглашении psql, например `student=!#`?', 'Пользователь — суперпользователь', 'Подключение под суперпользователем', 'На суперпользователя указывает символ # в конце приглашения.', NULL),
        ('option', 'Что означает восклицательный знак в приглашении psql, например `student=!#`?', 'Транзакция активна', 'Транзакция активна, ошибок пока не было', 'Активную транзакцию обозначает звёздочка.', NULL),
        ('option', 'Что делает ON_ERROR_ROLLBACK = on?', 'Сразу откатывает всю транзакцию при ошибке', 'Сразу откатывает всю транзакцию при первой ошибке', 'Наоборот: откатывается только ошибочная команда, а транзакция продолжается.', NULL),
        ('option', 'Что делает ON_ERROR_ROLLBACK = on?', 'Отключает режим автофиксации', 'Отключает режим автофиксации в сеансе', 'Автофиксацию отключает переменная AUTOCOMMIT.', NULL),
        ('option', 'Что делает ON_ERROR_ROLLBACK = on?', 'Ставит точку сохранения перед каждой командой и при ошибке откатывается к ней', 'Перед каждой командой ставит точку сохранения', 'Точка сохранения ставится перед каждой командой внутри транзакции; после ошибки транзакцию можно продолжить.', 'Точка сохранения ставится перед каждой командой внутри транзакции, и при ошибке откатывается только эта команда; транзакцию можно продолжить.'),
        ('option', 'Что делает команда \o файл?', 'Открывает файл в редакторе', 'Открывает файл в текстовом редакторе', 'Редактор открывает команда \e.', NULL),
        ('option', 'Что делает команда \o файл?', 'Выполняет команды из файла', 'Выполняет команды SQL из файла', 'Файл со скриптом выполняет команда \i.', NULL),
        ('option', 'Что делает команда \o файл?', 'Направляет вывод результатов запросов в файл', 'Пишет вывод запросов в файл', 'Результаты запросов пишутся в файл, пока не выполнить \o без аргументов.', NULL),
        ('option', 'Что делает команда \o файл?', 'Записывает историю команд', 'Записывает историю команд в файл', 'История сохраняется сама; записать её в файл можно командой \s файл.', NULL),
        ('option', 'Что делает команда \x?', 'Включает или выключает расширенный формат вывода для следующих запросов', 'Переключает расширенный формат вывода', 'Удобно, когда у записи много столбцов.', 'Включает или выключает расширенный формат для следующих запросов; удобно, когда у записи много столбцов.'),
        ('option', 'Что делает команда \x?', 'Выполняет запрос с расширенным выводом только один раз', 'Выполняет запрос с расширенным выводом один раз', 'Это делает \gx в конце запроса.', NULL),
        ('option', 'Что делает команда \x?', 'Завершает работу psql', 'Завершает работу psql без подтверждения', 'Это команда \q.', NULL),
        ('option', 'Что делает команда \x?', 'Направляет вывод в файл', 'Направляет вывод запросов в файл', 'Это команда \o.', NULL),
        ('option', 'Что переключает команда \t?', 'Вывод длительности выполнения команд', 'Вывод длительности выполнения каждой команды', 'Это делает \timing.', NULL),
        ('option', 'Какую переменную окружения проверяет psql, чтобы выбрать программу постраничного просмотра только для себя, не меняя её для других программ?', '`PGVIEWER`', '`PSQL_VIEWER`', 'Такой переменной psql не использует.', NULL),
        ('option', 'Что делает команда psql \! pwd?', 'Повторяет последний запрос', 'Повторяет последний запрос из буфера', 'Для этого служит \g без нового запроса.', NULL),
        ('option', 'Что делает команда psql \! pwd?', 'Отменяет текущую транзакцию', 'Выполняет pwd как функцию на сервере', 'Транзакцию отменяет команда SQL ROLLBACK.', 'Команду после \! выполняет оболочка на компьютере, где запущен psql, а не сервер.'),
        ('option', 'Что делает команда psql \! pwd?', 'Выполняет команду операционной системы pwd', 'Выполняет команду ОС pwd', '\! запускает команду оболочки ОС.', NULL),
        ('option', 'Что делает команда psql \! pwd?', 'Выводит историю команд', 'Выводит историю команд psql', 'История выводится командой \s.', NULL),
        ('option', 'Что показывает команда psql 16 \dconfig без шаблона имени параметра, в отличие от \dconfig *?', 'Только строки postgresql.conf, включая ошибки и повторные определения', 'Строки postgresql.conf, включая ошибочные и повторные', 'Команда показывает текущие значения параметров через pg_settings; строки файлов диагностируют через pg_file_settings.', NULL),
        ('option', 'Что показывает команда psql 16 \dconfig без шаблона имени параметра, в отличие от \dconfig *?', 'Только параметры, ожидающие перезапуска сервера', 'Параметры, ожидающие перезапуска сервера', 'Отбор без шаблона не ограничен признаком pending_restart.', NULL),
        ('option', 'Что показывает команда psql 16 \dconfig без шаблона имени параметра, в отличие от \dconfig *?', 'Параметры, установленные в значения, отличные от встроенных значений по умолчанию', 'Параметры со значениями, отличными от встроенных по умолчанию', 'Без шаблона команда отбирает параметры с источником не default и значением, отличным от boot_val.', NULL),
        ('option', 'psql запущен без ключа -U, переменная окружения PGUSER не задана. От имени какой роли он подключится?', 'Роли postgres', 'Роли postgres, главного суперпользователя кластера', 'postgres — обычное имя суперпользователя, но psql подставит его, только если так зовут пользователя ОС.', NULL),
        ('option', 'psql запущен без ключа -U, переменная окружения PGUSER не задана. От имени какой роли он подключится?', 'Роли с именем базы данных, указанной ключом -d', 'Роли с тем же именем, что у базы данных из ключа -d', 'Наоборот: если не указана база, её имя берётся из имени роли.', NULL),
        ('option', 'psql запущен без ключа -U, переменная окружения PGUSER не задана. От имени какой роли он подключится?', 'Роли с тем же именем, что у пользователя операционной системы, запустившего psql', 'Роли с именем пользователя ОС, запустившего psql', 'Если такой роли в кластере нет, подключение завершится ошибкой «роль не существует».', NULL),
        ('option', 'psql запущен без ключа -U, переменная окружения PGUSER не задана. От имени какой роли он подключится?', 'Роли public', 'Роли public, доступной всем пользователям', 'public — псевдороль, означающая всех; подключиться от её имени нельзя.', NULL),
        ('option', 'Переменная PGHOST не задана. Чем подключение psql -h localhost отличается от подключения без ключа -h на том же компьютере с Linux?', 'С -h localhost подключение идёт по TCP через петлевой интерфейс, без -h — через Unix-сокет', 'С -h localhost — по TCP, без -h — через Unix-сокет', 'Это видно в выводе \conninfo: «через сокет в …» или «компьютер localhost, адрес …».', 'С -h localhost подключение идёт по TCP через петлевой интерфейс, без -h — через Unix-сокет. Это видно в выводе \conninfo: «через сокет в …» или «компьютер localhost, адрес …».'),
        ('option', 'Что верно о справке в psql?', '\? — синтаксис команд SQL', '\? — синтаксис команд SQL, например SELECT', 'Синтаксис команд SQL показывает \h.', NULL),
        ('option', 'Что верно о справке в psql?', '\h — справка по метакомандам psql', '\h — справка по метакомандам psql, например \d', '\h показывает синтаксис команд SQL, например \h SELECT.', NULL),
        ('option', 'Что можно понять по стандартному приглашению psql?', 'Звёздочка после знака равенства, например student=*>, — открыт блок транзакции', 'Звёздочка после знака равенства — открыт блок транзакции', 'После COMMIT или ROLLBACK звёздочка пропадает.', 'Например, student=*>. После COMMIT или ROLLBACK звёздочка пропадает.'),
        ('option', 'Что можно понять по стандартному приглашению psql?', '# в конце приглашения — подключение под суперпользователем, > — под обычной ролью', '# в конце — суперпользователь, > — обычная роль', 'Например, postgres=# и student=>.', NULL),
        ('option', 'Что можно понять по стандартному приглашению psql?', 'Минус вместо знака равенства, например student->, — запрос не закончен и продолжается на следующей строке', 'Минус вместо знака равенства — запрос продолжается на следующей строке', 'Приглашение для второй и следующих строк задаёт переменная PROMPT2.', 'Например, student->. Приглашение для второй и следующих строк задаёт переменная PROMPT2.'),
        ('option', 'Что сделает эта команда psql?
```
\set wd `pwd`
```', 'Задаст переменную окружения ОС wd', 'Задаст переменную окружения ОС wd для psql', 'Переменную окружения задаёт \setenv; \set создаёт переменную psql.', NULL),
        ('option', 'Что сделает эта команда psql?
```
\set wd `pwd`
```', 'Запишет в переменную psql wd вывод команды ОС pwd — путь к текущему каталогу', 'Запишет в переменную psql wd вывод команды ОС pwd', 'Текст в обратных апострофах psql выполняет как команду оболочки и подставляет её вывод.', 'Текст в обратных апострофах psql выполняет как команду оболочки и подставляет её вывод — путь к текущему каталогу.'),
        ('option', 'Что сделает эта команда psql?
```
\set wd `pwd`
```', 'Выполнит на сервере функцию pwd', 'Выполнит на сервере функцию pwd и сохранит ответ', 'Команду в обратных апострофах выполняет оболочка на компьютере, где запущен psql, а не сервер.', NULL),
        ('option', 'Что сделает эта команда psql?
```
\set wd `pwd`
```', 'Запишет в переменную wd строку pwd', 'Запишет в переменную psql wd строку pwd', 'Строку без подстановки дали бы обычные апострофы: \set wd ''pwd''.', NULL),
        ('option', 'Как узнать штатный каталог, в котором psql ищет общесистемный файл настройки psqlrc?', 'Выполнить SHOW config_file;', 'Выполнить SHOW config_file; на сервере', 'Это путь к postgresql.conf сервера, а psqlrc — файл клиента psql.', NULL),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'Будут созданы переменные v1, v2 и v3', 'Будут созданы переменные v1, v2 и v3 по числу строк', '\gset не нумерует строки: имена переменных берутся из имён столбцов.', NULL),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'psql сообщит, что запрос вернул больше одной строки, и v сохранит прежнее значение', 'psql сообщит об ошибке, а v сохранит значение «старое»', '\gset требует ровно одну строку результата.', '\gset требует ровно одну строку результата: при нескольких строках psql сообщает, что запрос вернул больше одной строки, и ничего не записывает.'),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'В v запишется значение из последней строки', 'В v запишется 3 — значение из последней строки', 'При нескольких строках psql ничего не записывает и сообщает об ошибке.', NULL),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'В v запишется значение из первой строки', 'В v запишется 1 — значение из первой строки', 'При нескольких строках psql ничего не записывает и сообщает об ошибке.', NULL),
        ('option', 'Что подставляет спецификатор %I в функции format?', 'Номер позиции аргумента', 'Номер позиции аргумента в списке параметров', 'Номер аргумента задают иначе, например %1$I.', NULL),
        ('option', 'Что подставляет спецификатор %I в функции format?', 'Значение как имя объекта: при необходимости заключает его в двойные кавычки', 'Значение как имя объекта, в кавычках при надобности', 'format(''SELECT count(*) FROM %I'', ''my table'') даст SELECT count(*) FROM "my table".', NULL),
        ('option', 'Что подставляет спецификатор %I в функции format?', 'Значение как есть, без кавычек', 'Значение как есть, без кавычек и экранирования', 'Так подставляет %s.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
